<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">   $result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> + </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
